import numpy as np, json
from PIL import Image
root='/app/output/lift_approach_small'; meta=json.load(open(root+'/meta.json'))
for cam in ['top','front','oblique','side']:
 im=np.array(Image.open(root+'/last/'+cam+'.jpg'));d=np.load(root+'/depth_'+cam+'.npy')[0]
 H,W=im.shape[:2];yy,xx=np.indices((H,W));
 if cam=='top': roi=(xx>115)&(xx<210)&(yy>65)&(yy<145)
 elif cam=='front':roi=(xx>115)&(xx<220)&(yy>95)&(yy<160)
 elif cam=='oblique':roi=(xx>110)&(xx<215)&(yy>85)&(yy<170)
 else:roi=(xx>100)&(xx<180)&(yy>65)&(yy<155)
 # non-green low-saturation gray dark regions with valid depth
 m=roi&(d<2)&(d>0)&((im.max(2)-im.min(2))<50)&(im.mean(2)<180)
 # 4-connect components
 seen=np.zeros((H,W),bool); comps=[]
 for y,x in zip(*np.where(m)):
  if seen[y,x]:continue
  st=[(y,x)];seen[y,x]=1;pts=[]
  while st:
   a,b=st.pop();pts.append((a,b))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    c,e=a+dy,b+dx
    if 0<=c<H and 0<=e<W and m[c,e] and not seen[c,e]:seen[c,e]=1;st.append((c,e))
  if len(pts)>=8:
   ys=np.array([p[0] for p in pts]);xs=np.array([p[1] for p in pts]);ds=d[ys,xs]
   comps.append((len(pts),(int(xs.min()),int(xs.max()),int(ys.min()),int(ys.max())),round(float(np.median(ds)),3),tuple(np.round(np.median(im[ys,xs],axis=0)).astype(int))))
 print('\n',cam, sorted(comps,reverse=True)[:20])
