# row summary object pixels centers
for v in range(120,151,3):
 sel=roi[v]
 if sel.any(): print(v, np.where(sel)[0].min(),np.where(sel)[0].max(),np.round(np.median(w[np.where(ys==v)[0],:3],axis=0),3) if (ys==v).any() else '')
